    const dil = (i.query as { dil?: string }).dil === 'en' ? 'en' : 'tr'; const x = r[dil]!;
    return { baslik: x.baslik, adimlar: x.adimlar, web: x.web.replace(/\[(web adresi|web address)\]/, b.webAdresi), guvenlik: x.guvenlik };
